css:
.pbd-margin-summary{--tx:#e3e8f1;--dim:#7d879b;--ln:rgba(255,255,255,.08);--up:#3ddc97;--dn:#ff6b6b;--wr:#f5b83d;--ac:#6aa8ff;box-sizing:border-box;width:100%;display:flex;flex-direction:column;gap:7px;padding:9px 10px 8px;background:linear-gradient(180deg,#121722 0%,#0b0e15 100%);border:1px solid var(--ln);border-radius:8px;color:var(--tx);font:10px/1.25 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;outline:none}
.pbd-margin-summary:focus-visible{box-shadow:0 0 0 1px var(--ac)}
.pbd-margin-summary *{box-sizing:border-box}
.pbd-margin-summary-hd{display:flex;justify-content:space-between;align-items:flex-start;gap:8px}
.pbd-margin-summary-id{min-width:0}
.pbd-margin-summary-id b{display:block;font-size:10.5px;font-weight:650;letter-spacing:.08em}
.pbd-margin-summary-id span{display:block;margin-top:2px;font-size:8px;letter-spacing:.05em;color:var(--dim);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pbd-margin-summary-tabs{display:flex;flex:none;border:1px solid var(--ln);border-radius:4px;overflow:hidden}
.pbd-margin-summary-tab{appearance:none;border:0;margin:0;background:transparent;color:var(--dim);font:600 9px/1 ui-monospace,Menlo,Consolas,monospace;padding:4px 7px;cursor:pointer}
.pbd-margin-summary-tab+.pbd-margin-summary-tab{border-left:1px solid var(--ln)}
.pbd-margin-summary-tab:hover{color:var(--tx)}
.pbd-margin-summary-tab[aria-selected="true"]{background:rgba(106,168,255,.18);color:#d4e4ff}
.pbd-margin-summary-kpis{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:5px}
.pbd-margin-summary-kpi{min-width:0;padding:5px 6px;border:1px solid var(--ln);border-radius:5px;background:rgba(255,255,255,.025)}
.pbd-margin-summary-kpi span{display:block;font-size:7.5px;letter-spacing:.1em;color:var(--dim);white-space:nowrap}
.pbd-margin-summary-kpi b{display:block;margin-top:4px;font:600 13px/1 ui-monospace,Menlo,Consolas,monospace;font-variant-numeric:tabular-nums;white-space:nowrap}
.pbd-margin-summary-kpi i{display:block;margin-top:3px;font:normal 8.5px/1 ui-monospace,Menlo,Consolas,monospace;font-variant-numeric:tabular-nums;color:var(--dim);white-space:nowrap}
.pbd-margin-summary-gauge{display:flex;flex-direction:column;gap:2px}
.pbd-margin-summary-track{position:relative;height:9px;border:1px solid var(--ln);border-radius:2px;overflow:hidden;background:linear-gradient(90deg,rgba(61,220,151,.10) 0 75%,rgba(245,184,61,.16) 75% 90%,rgba(255,107,107,.18) 90% 100%)}
.pbd-margin-summary-fill{position:absolute;left:0;top:0;bottom:0;width:0;background:var(--up);transition:width .6s cubic-bezier(.2,.7,.2,1),background-color .3s}
.pbd-margin-summary[data-st="warn"] .pbd-margin-summary-fill{background:var(--wr)}
.pbd-margin-summary[data-st="call"] .pbd-margin-summary-fill{background:var(--dn)}
.pbd-margin-summary-mk{position:absolute;top:0;bottom:0;width:1px;background:rgba(255,255,255,.6)}
.pbd-margin-summary-scale{position:relative;height:9px;font:7.5px/1 ui-monospace,Menlo,Consolas,monospace;color:var(--dim)}
.pbd-margin-summary-scale span{position:absolute;top:1px;white-space:nowrap}
.pbd-margin-summary-scale .pbd-margin-summary-c{transform:translateX(-50%)}
.pbd-margin-summary-gl{display:flex;justify-content:space-between;gap:6px;font-size:8.5px;letter-spacing:.06em;color:var(--dim)}
.pbd-margin-summary-gl b{font:600 10px/1 ui-monospace,Menlo,Consolas,monospace;color:var(--tx);font-variant-numeric:tabular-nums}
.pbd-margin-summary-state{font:600 8.5px/1.2 ui-monospace,Menlo,Consolas,monospace;letter-spacing:.02em;text-align:right}
.pbd-margin-summary[data-st="ok"] .pbd-margin-summary-state{color:var(--up)}
.pbd-margin-summary[data-st="warn"] .pbd-margin-summary-state{color:var(--wr)}
.pbd-margin-summary[data-st="call"] .pbd-margin-summary-state{color:var(--dn)}
.pbd-margin-summary-tbl{width:100%;border-collapse:collapse;font-size:9.5px}
.pbd-margin-summary-tbl th{padding:0 0 3px 6px;border-bottom:1px solid var(--ln);font-size:7.5px;font-weight:500;letter-spacing:.08em;color:var(--dim);text-align:right;white-space:nowrap}
.pbd-margin-summary-tbl th:first-child{padding-left:0;text-align:left}
.pbd-margin-summary-tbl td{padding:2.5px 0 2.5px 6px;border-bottom:1px solid rgba(255,255,255,.04);text-align:right;font-family:ui-monospace,Menlo,Consolas,monospace;font-variant-numeric:tabular-nums;white-space:nowrap}
.pbd-margin-summary-tbl td:first-child{width:100%;max-width:0;padding-left:0;text-align:left;font-family:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;color:#c3cbd8;overflow:hidden;text-overflow:ellipsis}
.pbd-margin-summary-tbl tfoot td{border-top:1px solid rgba(255,255,255,.14);border-bottom:0;font-weight:650;color:var(--tx)}
.pbd-margin-summary-tbl tfoot td:first-child{font-size:8px;letter-spacing:.08em;color:var(--tx)}
.pbd-margin-summary-up,.pbd-margin-summary-kpi i.pbd-margin-summary-up{color:var(--up)}
.pbd-margin-summary-dn,.pbd-margin-summary-kpi i.pbd-margin-summary-dn{color:var(--dn)}
.pbd-margin-summary-ft{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:3px 7px;padding-top:5px;border-top:1px solid var(--ln);font-size:7px;letter-spacing:.05em;color:var(--dim)}
.pbd-margin-summary-ft span{display:flex;justify-content:space-between;gap:4px;white-space:nowrap}
.pbd-margin-summary-ft b{font:600 8.5px/1 ui-monospace,Menlo,Consolas,monospace;letter-spacing:0;color:var(--tx);font-variant-numeric:tabular-nums}
.pbd-margin-summary-hint{display:flex;justify-content:space-between;font-size:7.5px;letter-spacing:.06em;color:#5b6477}
.pbd-margin-summary-hint b{font-weight:500;color:var(--dim)}
@media (prefers-reduced-motion: reduce){
.pbd-margin-summary-fill{transition:none}
.pbd-margin-summary *{transition:none!important;animation:none!important}
}

js:
var S = [
  {t:'T',   d:'24-SEP-26', lmv:2412.6, smv:-1896.3, cash:326.1, c:[388.4,62.7,41.3,18.9,9.2]},
  {t:'T-1', d:'23-SEP-26', lmv:2398.1, smv:-1902.7, cash:331.0, c:[391.2,60.4,40.8,19.6,9.0]},
  {t:'T-5', d:'17-SEP-26', lmv:2455.9, smv:-1841.2, cash:188.5, c:[452.1,84.3,52.0,32.5,9.8]}
];
var N = ['Portfolio stress (TIMS &plusmn;15%)','Single-name concentration','Liquidity (position &gt; 20% ADV)','HTB short add-on','FX &amp; residual'];
var WARN = 75, CALL = 90, cur = 0;
function q(k){ return root.querySelector('[data-k="'+k+'"]'); }
function r1(v){ return Math.round(v*10 + (v >= 0 ? 1e-7 : -1e-7))/10; }
function f(v,d){ return Math.abs(v).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d}); }
function n(v,d){ var r = Number(v.toFixed(d)); return (r < 0 ? '−' : '') + f(r,d); }
function sg(v,d){ var r = Number(v.toFixed(d)); return (r > 0 ? '+' : r < 0 ? '−' : '') + f(r,d); }
function sum(a){ return a.reduce(function(x,y){ return x+y; },0); }
function lr(vals,dp){
  var m = Math.pow(10,dp), tot = sum(vals);
  var raw = vals.map(function(v){ return v/tot*100*m; }), fl = raw.map(Math.floor);
  var rem = Math.round(100*m - sum(fl));
  var ix = raw.map(function(v,i){ return i; }).sort(function(a,b){ return (raw[b]-fl[b]) - (raw[a]-fl[a]); });
  for (var k = 0; k < rem; k++) fl[ix[k % ix.length]]++;
  return fl.map(function(v){ return v/m; });
}
function calc(s){
  var o = {};
  o.eq = r1(s.lmv + s.smv + s.cash);
  o.req = r1(sum(s.c));
  o.exc = r1(o.eq - o.req);
  o.util = o.req / o.eq * 100;
  o.gross = r1(s.lmv - s.smv);
  o.net = r1(s.lmv + s.smv);
  o.lev = o.gross / o.eq;
  return o;
}
function delta(el, v, goodUp){
  if (v === null){ el.textContent = '— no prior'; el.className = ''; return; }
  var r = Number(v.toFixed(1));
  el.textContent = (r > 0 ? '▲ ' : r < 0 ? '▼ ' : '● ') + sg(v,1);
  el.className = r === 0 ? '' : ((r > 0) === goodUp ? 'pbd-margin-summary-up' : 'pbd-margin-summary-dn');
}
function render(){
  var s = S[cur], o = calc(s), p = S[cur+1] ? calc(S[cur+1]) : null, ps = S[cur+1] || null;
  root.querySelectorAll('.pbd-margin-summary-tab').forEach(function(b,i){ b.setAttribute('aria-selected', i === cur ? 'true' : 'false'); });
  q('eq').textContent = '$' + f(o.eq,1) + 'M';
  q('req').textContent = '$' + f(o.req,1) + 'M';
  q('exc').textContent = (o.exc < 0 ? '−$' : '$') + f(o.exc,1) + 'M';
  delta(q('deq'), p ? o.eq - p.eq : null, true);
  delta(q('dreq'), p ? o.req - p.req : null, false);
  delta(q('dexc'), p ? o.exc - p.exc : null, true);
  var st = o.util >= CALL ? 'call' : o.util >= WARN ? 'warn' : 'ok';
  root.setAttribute('data-st', st);
  q('util').textContent = f(o.util,2) + '%';
  root.querySelector('.pbd-margin-summary-fill').style.width = Math.min(100, o.util) + '%';
  var toWarn = r1(o.eq*WARN/100 - o.req), toCall = r1(o.eq*CALL/100 - o.req);
  q('state').textContent = st === 'ok' ? '● WITHIN · ' + f(toWarn,1) + 'M TO WARN'
    : st === 'warn' ? '▲ WARN · ' + f(toCall,1) + 'M TO CALL'
    : '■ CALL · SHORTFALL ' + f(-toCall,1) + 'M';
  var pct = lr(s.c,1), rows = '';
  s.c.forEach(function(v,i){
    var d = ps ? r1(v - ps.c[i]) : null;
    var cls = d === null || d === 0 ? '' : (d > 0 ? 'pbd-margin-summary-dn' : 'pbd-margin-summary-up');
    rows += '<tr><td>' + N[i] + '</td><td>' + f(v,1) + '</td><td>' + f(pct[i],1) + '</td><td class="' + cls + '">' + (d === null ? '—' : sg(d,1)) + '</td></tr>';
  });
  root.querySelector('.pbd-margin-summary-tbl tbody').innerHTML = rows;
  q('dh').textContent = ps ? 'Δ vs ' + ps.t : 'Δ';
  q('tot').textContent = f(o.req,1);
  var dt = p ? r1(o.req - p.req) : null;
  q('dtot').textContent = dt === null ? '—' : sg(dt,1);
  q('dtot').className = dt === null || dt === 0 ? '' : (dt > 0 ? 'pbd-margin-summary-dn' : 'pbd-margin-summary-up');
  q('lmv').textContent = f(s.lmv,1);
  q('smv').textContent = n(s.smv,1);
  q('gross').textContent = f(o.gross,1);
  q('net').textContent = sg(o.net,1);
  q('cash').textContent = sg(s.cash,1);
  q('lev').textContent = o.lev.toFixed(2) + 'x';
  q('asof').textContent = s.d;
}
root.querySelectorAll('.pbd-margin-summary-tab').forEach(function(b){
  b.addEventListener('click', function(){ cur = Number(b.getAttribute('data-i')); render(); });
});
root.addEventListener('keydown', function(e){
  if (e.key === 'ArrowRight'){ cur = Math.min(S.length-1, cur+1); render(); e.preventDefault(); }
  else if (e.key === 'ArrowLeft'){ cur = Math.max(0, cur-1); render(); e.preventDefault(); }
  else if (e.key === '1' || e.key === '2' || e.key === '3'){ cur = Number(e.key)-1; render(); }
});
render();

css:
.pbd-borrow-board{--tx:#e3e8f1;--dim:#7d879b;--ln:rgba(255,255,255,.08);--up:#3ddc97;--dn:#ff6b6b;--wr:#f5b83d;--or:#ff9950;--ac:#6aa8ff;box-sizing:border-box;width:100%;display:flex;flex-direction:column;gap:6px;padding:9px 10px 8px;background:linear-gradient(180deg,#121722 0%,#0b0e15 100%);border:1px solid var(--ln);border-radius:8px;color:var(--tx);font:10px/1.25 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;outline:none}
.pbd-borrow-board:focus-visible{box-shadow:0 0 0 1px var(--ac)}
.pbd-borrow-board *{box-sizing:border-box}
.pbd-borrow-board-hd{display:flex;justify-content:space-between;align-items:flex-start;gap:8px}
.pbd-borrow-board-id{min-width:0}
.pbd-borrow-board-id b{display:block;font-size:10.5px;font-weight:650;letter-spacing:.08em}
.pbd-borrow-board-id span{display:block;margin-top:2px;font-size:8px;letter-spacing:.05em;color:var(--dim);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pbd-borrow-board-clk{flex:none;font:600 9px/1 ui-monospace,Menlo,Consolas,monospace;color:#9fb3d6;font-variant-numeric:tabular-nums;padding:3px 5px;border:1px solid var(--ln);border-radius:3px}
.pbd-borrow-board-sum{display:flex;flex-wrap:wrap;gap:4px}
.pbd-borrow-board-chip{display:inline-flex;align-items:center;gap:4px;padding:2px 6px;border:1px solid var(--ln);border-radius:10px;font:600 8px/1.2 ui-monospace,Menlo,Consolas,monospace;letter-spacing:.04em;color:var(--dim)}
.pbd-borrow-board-chip b{color:var(--tx);font-weight:650}
.pbd-borrow-board-scroll{max-height:154px;overflow:auto;border:1px solid var(--ln);border-radius:4px;scrollbar-width:thin;scrollbar-color:#2a3242 transparent}
.pbd-borrow-board-tbl{width:100%;border-collapse:collapse;font:9.5px/1.2 ui-monospace,Menlo,Consolas,monospace;font-variant-numeric:tabular-nums}
.pbd-borrow-board-tbl th{position:sticky;top:0;z-index:1;padding:4px 4px 3px;background:#131926;border-bottom:1px solid var(--ln);font:500 7.5px/1 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;letter-spacing:.08em;color:var(--dim);text-align:right;white-space:nowrap;cursor:default;user-select:none}
.pbd-borrow-board-tbl th[data-s]{cursor:pointer}
.pbd-borrow-board-tbl th[data-s]:hover{color:var(--tx)}
.pbd-borrow-board-tbl th:first-child{text-align:left}
.pbd-borrow-board-tbl th:last-child{text-align:center}
.pbd-borrow-board-tbl th.pbd-borrow-board-on{color:#cfe0ff}
.pbd-borrow-board-tbl td{padding:3px 4px;border-bottom:1px solid rgba(255,255,255,.04);text-align:right;white-space:nowrap}
.pbd-borrow-board-tbl th:last-child,.pbd-borrow-board-tbl td:last-child{padding-right:9px}
.pbd-borrow-board-tbl td:first-child{text-align:left;font-weight:650;color:#dfe6f2}
.pbd-borrow-board-tbl td:last-child{text-align:center}
.pbd-borrow-board-tbl tr{cursor:pointer}
.pbd-borrow-board-tbl tbody tr:hover{background:rgba(255,255,255,.035)}
.pbd-borrow-board-tbl tr.pbd-borrow-board-cur{background:rgba(106,168,255,.14);box-shadow:inset 2px 0 0 var(--ac)}
.pbd-borrow-board-tbl tr.pbd-borrow-board-fl td{animation:pbd-borrow-board-flash .9s ease-out}
.pbd-borrow-board-tbl td.pbd-borrow-board-zero{color:var(--dn)}
.pbd-borrow-board-up{color:var(--dn)}
.pbd-borrow-board-dn{color:var(--up)}
.pbd-borrow-board-flat{color:var(--dim)}
.pbd-borrow-board-t{display:inline-block;min-width:30px;padding:1px 3px;border-radius:2px;font:700 7.5px/1.2 ui-monospace,Menlo,Consolas,monospace;letter-spacing:.05em;text-align:center}
.pbd-borrow-board-t-gc{background:rgba(61,220,151,.12);color:var(--up)}
.pbd-borrow-board-t-warm{background:rgba(245,184,61,.14);color:var(--wr)}
.pbd-borrow-board-t-htb{background:rgba(255,153,80,.18);color:var(--or)}
.pbd-borrow-board-t-spcl{background:rgba(255,107,107,.2);color:#ff8a8a;box-shadow:inset 0 0 0 1px rgba(255,107,107,.45)}
.pbd-borrow-board-loc{display:flex;align-items:center;gap:6px;padding:4px 5px;border:1px solid var(--ln);border-radius:4px;background:rgba(255,255,255,.02)}
.pbd-borrow-board-ll{font-size:7.5px;letter-spacing:.1em;color:var(--dim)}
.pbd-borrow-board-q{width:78px;min-width:0;padding:3px 5px;border:1px solid #2a3242;border-radius:3px;background:#0a0d14;color:var(--tx);font:600 10px/1 ui-monospace,Menlo,Consolas,monospace;font-variant-numeric:tabular-nums;text-align:right;outline:none}
.pbd-borrow-board-q:focus{border-color:var(--ac)}
.pbd-borrow-board-sel{flex:1;min-width:0;font:700 10px/1 ui-monospace,Menlo,Consolas,monospace;color:#cfe0ff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pbd-borrow-board-go{flex:none;appearance:none;margin:0;padding:4px 7px;border:1px solid rgba(106,168,255,.5);border-radius:3px;background:rgba(106,168,255,.14);color:#d4e4ff;font:700 8.5px/1 ui-monospace,Menlo,Consolas,monospace;letter-spacing:.05em;cursor:pointer}
.pbd-borrow-board-go:hover{background:rgba(106,168,255,.26)}
.pbd-borrow-board-log{min-height:11px;font:8.5px/1.3 ui-monospace,Menlo,Consolas,monospace;color:var(--dim);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pbd-borrow-board-log.pbd-borrow-board-ok{color:var(--up)}
.pbd-borrow-board-log.pbd-borrow-board-part{color:var(--wr)}
.pbd-borrow-board-log.pbd-borrow-board-rej{color:var(--dn)}
@keyframes pbd-borrow-board-flash{0%{background:rgba(245,184,61,.32)}100%{background:transparent}}
@media (prefers-reduced-motion: reduce){
.pbd-borrow-board-tbl tr.pbd-borrow-board-fl td{animation:none}
.pbd-borrow-board *{animation:none!important;transition:none!important}
}

js:
var R = [
  ['BYND',1858000,1648000,3450,3380],['UPST',1910000,1270000,1180,1215],['CVNA',1831000,1011000,760,735],
  ['PLUG',3237000,1337000,420,420],['SMCI',1730000,630000,350,310],['LCID',3913000,1213000,295,300],
  ['RIVN',4005000,905000,185,170],['AMC',6660000,1860000,140,140],['GME',1152000,212000,88,95],
  ['TSLA',6465000,265000,45,40],['NVDA',9670000,271000,30,30],['AAPL',18830000,226000,25,25],
  ['MSFT',12210000,110000,25,25]
];
var rows = R.map(function(r){ return {t:r[0], L:r[1], O:r[2], f:r[3], p:r[4]}; });
var ord = rows.slice(), sel = rows[3], sortKey = 'f', sortDir = -1, locN = 48212;
var tb = root.querySelector('.pbd-borrow-board-tbl tbody'), inp = root.querySelector('.pbd-borrow-board-q');
var logEl = root.querySelector('.pbd-borrow-board-log'), selEl = root.querySelector('.pbd-borrow-board-sel');
var scroller = root.querySelector('.pbd-borrow-board-scroll');
function g(v){ return v.toLocaleString('en-US'); }
function av(r){ return r.L - r.O; }
function ut(r){ return r.O / r.L * 100; }
function tier(fee){ return fee <= 35 ? 'GC' : fee <= 300 ? 'WARM' : fee <= 1000 ? 'HTB' : 'SPCL'; }
function sortRows(){
  var key = {t:function(r){ return r.t; }, a:av, f:function(r){ return r.f; }, u:ut}[sortKey];
  ord.sort(function(a,b){ var x = key(a), y = key(b); return (x < y ? -1 : x > y ? 1 : 0) * sortDir; });
  root.querySelectorAll('.pbd-borrow-board-tbl th').forEach(function(th){
    th.classList.toggle('pbd-borrow-board-on', th.getAttribute('data-s') === sortKey);
  });
}
function summary(){
  var c = {GC:0, WARM:0, HTB:0, SPCL:0};
  rows.forEach(function(r){ c[tier(r.f)]++; });
  root.querySelector('.pbd-borrow-board-sum').innerHTML = ['GC','WARM','HTB','SPCL'].map(function(k){
    return '<span class="pbd-borrow-board-chip"><i class="pbd-borrow-board-t pbd-borrow-board-t-' + k.toLowerCase() + '">' + k + '</i><b>' + c[k] + '</b></span>';
  }).join('') + '<span class="pbd-borrow-board-chip">GC &le;35 &middot; HTB &gt;300 &middot; SPCL &gt;1,000</span>';
}
function render(flashRow){
  var h = '';
  ord.forEach(function(r,i){
    var d = r.f - r.p, a = av(r), t = tier(r.f);
    var dc = d > 0 ? 'pbd-borrow-board-up' : d < 0 ? 'pbd-borrow-board-dn' : 'pbd-borrow-board-flat';
    var ds = d > 0 ? '▲' + g(d) : d < 0 ? '▼' + g(-d) : '0';
    h += '<tr data-i="' + i + '" class="' + (r === sel ? 'pbd-borrow-board-cur' : '') + (r === flashRow ? ' pbd-borrow-board-fl' : '') + '">' +
      '<td>' + r.t + '</td><td class="' + (a === 0 ? 'pbd-borrow-board-zero' : '') + '">' + g(Math.round(a/1000)) + '</td>' +
      '<td>' + g(r.f) + '</td><td class="' + dc + '">' + ds + '</td><td>' + ut(r).toFixed(1) + '%</td>' +
      '<td><i class="pbd-borrow-board-t pbd-borrow-board-t-' + t.toLowerCase() + '">' + t + '</i></td></tr>';
  });
  tb.innerHTML = h;
  selEl.textContent = sel.t + ' @ ' + g(sel.f) + 'bps';
  summary();
}
function ensureVisible(){
  var tr = tb.querySelector('.pbd-borrow-board-cur');
  if (!tr) return;
  var top = tr.offsetTop - 20, bot = tr.offsetTop + tr.offsetHeight;
  if (top < scroller.scrollTop) scroller.scrollTop = top;
  else if (bot > scroller.scrollTop + scroller.clientHeight) scroller.scrollTop = bot - scroller.clientHeight;
}
function log(msg, cls){ logEl.textContent = msg; logEl.className = 'pbd-borrow-board-log ' + (cls || ''); }
function request(){
  var qty = parseInt(inp.value.replace(/[^0-9]/g,''), 10) || 0, a = av(sel);
  if (qty <= 0){ log('REJECTED · enter a share quantity', 'pbd-borrow-board-rej'); return; }
  locN++;
  if (a <= 0){ log('LOC-' + locN + ' REJECTED · ' + sel.t + ' no availability · try PB HTB desk', 'pbd-borrow-board-rej'); return; }
  var got = Math.min(qty, a);
  sel.O += got;
  if (got < qty) log('LOC-' + locN + ' PARTIAL ' + g(got) + ' of ' + g(qty) + ' ' + sel.t + ' @ ' + g(sel.f) + 'bps', 'pbd-borrow-board-part');
  else log('LOC-' + locN + ' APPROVED ' + g(got) + ' ' + sel.t + ' @ ' + g(sel.f) + 'bps · exp 16:00', 'pbd-borrow-board-ok');
  render(sel);
}
tb.addEventListener('click', function(e){
  var tr = e.target.closest('tr');
  if (!tr) return;
  sel = ord[Number(tr.getAttribute('data-i'))];
  render();
});
root.querySelectorAll('.pbd-borrow-board-tbl th[data-s]').forEach(function(th){
  th.addEventListener('click', function(){
    var k = th.getAttribute('data-s');
    if (k === sortKey) sortDir = -sortDir; else { sortKey = k; sortDir = k === 't' ? 1 : -1; }
    sortRows(); render();
  });
});
root.querySelector('.pbd-borrow-board-go').addEventListener('click', request);
inp.addEventListener('blur', function(){ var v = parseInt(inp.value.replace(/[^0-9]/g,''), 10); if (v > 0) inp.value = g(v); });
root.addEventListener('keydown', function(e){
  if (e.key === 'Enter' && e.target.tagName === 'BUTTON') return;
  var i = ord.indexOf(sel);
  if (e.key === 'ArrowDown'){ sel = ord[Math.min(ord.length-1, i+1)]; render(); ensureVisible(); e.preventDefault(); }
  else if (e.key === 'ArrowUp'){ sel = ord[Math.max(0, i-1)]; render(); ensureVisible(); e.preventDefault(); }
  else if (e.key === 'Enter'){ request(); e.preventDefault(); }
});
var sec = 10*3600 + 42*60 + 7, n = 0;
function pad(v){ return (v < 10 ? '0' : '') + v; }
function tick(){
  if (!root.isConnected) return;
  sec++; n++;
  root.querySelector('.pbd-borrow-board-clk').textContent = pad(Math.floor(sec/3600)) + ':' + pad(Math.floor(sec/60)%60) + ':' + pad(sec%60) + ' ET';
  if (n % 3 === 0){
    var pool = rows.filter(function(r){ return r.f > 35; });
    var r = pool[Math.floor(Math.random()*pool.length)];
    var steps = [-15,-10,-5,5,10,15,25], k = Math.max(1, Math.round(r.f/400));
    r.f = Math.max(40, Math.round((r.f + steps[Math.floor(Math.random()*steps.length)]*k)/5)*5);
    if (sortKey === 'f') sortRows();
    render(r);
  }
  setTimeout(tick, 1000);
}
sortRows(); render();
setTimeout(tick, 1000);

