var A = [
  ['USD cash',                 326.1,  0.0,  0.0, 100],
  ['UST bills 0-1Y',           180.0,  0.5,  1.0, 100],
  ['UST notes 1-10Y',          245.4,  2.0,  4.0, 100],
  ['UST bonds 10Y+',            96.8,  5.0, 10.0,  50],
  ['Agency MBS (TBA-eligible)', 64.2,  6.0, 12.0,  25],
  ['G10 sovereign ex-US',      118.7,  4.0,  8.0,  40],
  ['IG corporate',              88.3,  8.0, 15.0,  25],
  ['HY corporate',              42.5, 20.0, 35.0,   5],
  ['Equity large cap (S&amp;P 500)', 1640.2, 15.0, 25.0, 60],
  ['Equity small cap (R2000)', 412.7, 25.0, 40.0,  10],
  ['Equity EM ADR',             84.9, 30.0, 45.0,   5],
  ['Convertible bonds',         38.0, 35.0, 50.0, 2.5]
];
var mode = 0, cur = 9;
function q(k){ return root.querySelector('[data-k="'+k+'"]'); }
function r1(v){ return Math.round(v*10 + (v >= 0 ? 1e-7 : -1e-7))/10; }
function f(v,d){ return Math.abs(v).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d}); }
function lr(vals,dp){
  var m = Math.pow(10,dp), tot = vals.reduce(function(a,b){ return a+b; },0);
  var raw = vals.map(function(v){ return v/tot*100*m; }), fl = raw.map(Math.floor);
  var rem = Math.round(100*m - fl.reduce(function(a,b){ return a+b; },0));
  var ix = raw.map(function(v,i){ return i; }).sort(function(a,b){ return (raw[b]-fl[b]) - (raw[a]-fl[a]); });
  for (var k = 0; k < rem; k++) fl[ix[k % ix.length]]++;
  return fl.map(function(v){ return v/m; });
}
function compute(){
  var rows = A.map(function(a){
    var hc = mode ? a[3] : a[2];
    return {n:a[0], mv:a[1], hc:hc, base:a[2], cv:r1(a[1]*(1-hc/100)), cap:a[4]};
  });
  var tmv = r1(rows.reduce(function(s,r){ return s + r.mv; },0));
  var tcv = r1(rows.reduce(function(s,r){ return s + r.cv; },0));
  var sh = lr(rows.map(function(r){ return r.cv; }), 1);
  var inel = 0;
  rows.forEach(function(r,i){
    r.sh = sh[i];
    r.raw = r.cv / tcv * 100;
    r.inel = Math.max(0, r1(r.cv - r.cap/100*tcv));
    inel = r1(inel + r.inel);
  });
  return {rows:rows, tmv:tmv, tcv:tcv, inel:inel, el:r1(tcv - inel), whc:(1 - tcv/tmv)*100};
}
function render(){
  var o = compute(), h = '';
  root.setAttribute('data-m', String(mode));
  root.querySelectorAll('.pbd-collateral-sched-seg button').forEach(function(b){
    b.setAttribute('aria-selected', Number(b.getAttribute('data-m')) === mode ? 'true' : 'false');
  });
  o.rows.forEach(function(r,i){
    var br = r.inel > 0, near = !br && r.cap < 100 && r.raw >= r.cap*0.85;
    var w = Math.min(100, r.raw / r.cap * 100);
    h += '<tr data-i="' + i + '"' + (i === cur ? ' class="pbd-collateral-sched-cur"' : '') + '>' +
      '<td>' + r.n + '</td><td>' + f(r.mv,1) + '</td>' +
      '<td' + (mode && r.hc !== r.base ? ' class="pbd-collateral-sched-hcx"' : '') + '>' + f(r.hc,1) + '</td>' +
      '<td>' + f(r.cv,1) + '</td>' +
      '<td><span class="pbd-collateral-sched-cc' + (br ? ' pbd-collateral-sched-br' : near ? ' pbd-collateral-sched-nr' : '') + '">' +
      (br ? '▲' : '') + f(r.sh,1) + '<i>/' + (r.cap % 1 ? f(r.cap,1) : r.cap) + '</i>' +
      '<span class="pbd-collateral-sched-bar"><em style="width:' + w.toFixed(1) + '%"></em></span></span></td></tr>';
  });
  root.querySelector('.pbd-collateral-sched-tbl tbody').innerHTML = h;
  q('mv').textContent = f(o.tmv,1);
  q('cv').textContent = f(o.tcv,1);
  q('hc').textContent = f(o.whc,2) + '%';
  q('el').textContent = f(o.el,1);
  q('tmv').textContent = f(o.tmv,1);
  q('thc').textContent = f(o.whc,2);
  q('tcv').textContent = f(o.tcv,1);
  q('inel').textContent = o.inel > 0 ? '−' + f(o.inel,1) + ' INELIGIBLE (CONC)' : 'NO CONCENTRATION HAIRCUT';
  var r = o.rows[cur];
  var capAmt = r1(r.cap/100*o.tcv);
  root.querySelector('.pbd-collateral-sched-det').innerHTML =
    '<b>' + r.n + '</b> &middot; ' + (mode ? 'STRESS' : 'BASE') + ' schedule<br>' +
    f(r.mv,1) + ' &times; (1 &minus; ' + f(r.hc,1) + '%) = <b>' + f(r.cv,1) + '</b> &middot; ' +
    (r.inel > 0
      ? '<span class="pbd-collateral-sched-br">' + f(r.raw,2) + '% of CV &gt; ' + r.cap + '% cap (' + f(capAmt,1) + ') &rArr; &minus;' + f(r.inel,1) + ' ineligible</span>'
      : '<span class="pbd-collateral-sched-okc">' + f(r.raw,2) + '% of CV &le; ' + r.cap + '% cap &check;</span>');
}
function ensureVisible(){
  var sc = root.querySelector('.pbd-collateral-sched-scroll'), tr = root.querySelector('.pbd-collateral-sched-cur');
  if (!tr) return;
  var top = tr.offsetTop - 20, bot = tr.offsetTop + tr.offsetHeight + 20;
  if (top < sc.scrollTop) sc.scrollTop = top;
  else if (bot > sc.scrollTop + sc.clientHeight) sc.scrollTop = bot - sc.clientHeight;
}
root.querySelector('.pbd-collateral-sched-tbl tbody').addEventListener('click', function(e){
  var tr = e.target.closest('tr');
  if (tr){ cur = Number(tr.getAttribute('data-i')); render(); }
});
root.querySelectorAll('.pbd-collateral-sched-seg button').forEach(function(b){
  b.addEventListener('click', function(){ mode = Number(b.getAttribute('data-m')); render(); });
});
root.addEventListener('keydown', function(e){
  if (e.key === 'ArrowDown'){ cur = Math.min(A.length-1, cur+1); render(); ensureVisible(); e.preventDefault(); }
  else if (e.key === 'ArrowUp'){ cur = Math.max(0, cur-1); render(); ensureVisible(); e.preventDefault(); }
  else if (e.key === 's' || e.key === 'S' || e.key === 'F2'){ mode = mode ? 0 : 1; render(); e.preventDefault(); }
});
render();

