var V = [{k:'1D',d:1,u:1,x:'',h:'P&amp;L $/day'},{k:'MTD',d:MTD,u:1,x:'',h:'P&amp;L $ MTD'},{k:'ANN',d:365,u:1000,x:'K',h:'P&amp;L $K p.a.'}];
var view = 0, cur = 0;
function q(k){ return root.querySelector('[data-k="'+k+'"]'); }
function g(v){ return Math.abs(v).toLocaleString('en-US',{maximumFractionDigits:0}); }
function sg(v){ return (v > 0 ? '+' : v < 0 ? '−' : '') + g(v); }
function f(v,d){ return Math.abs(v).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d}); }
function cls(v){ return v > 0 ? 'pbd-financing-cost-pos' : v < 0 ? 'pbd-financing-cost-neg' : ''; }
function daily(l){ return l.s * l.bal * 1e6 * (l.bm + l.sp) / 100 / 360; }
function dailyBm(l){ return l.s * l.bal * 1e6 * l.bm / 100 / 360; }
function vals(days, u){
  return L.map(function(l){
    var tot = Math.round(daily(l) * days / u), bm = Math.round(dailyBm(l) * days / u);
    return {tot:tot, bm:bm, sp:tot - bm};
  });
}
function render(){
  var v = V[view], rs = vals(v.d, v.u), max = 0, net = 0, bm = 0, sp = 0, h = '';
  rs.forEach(function(r){ max = Math.max(max, Math.abs(r.tot)); net += r.tot; bm += r.bm; sp += r.sp; });
  root.querySelectorAll('.pbd-financing-cost-seg button').forEach(function(b){
    b.setAttribute('aria-selected', Number(b.getAttribute('data-v')) === view ? 'true' : 'false');
  });
  L.forEach(function(l,i){
    var r = rs[i], w = Math.abs(r.tot) / max * 50;
    var pos = r.tot >= 0 ? 'left:50%;width:' + w.toFixed(2) + '%' : 'left:' + (50 - w).toFixed(2) + '%;width:' + w.toFixed(2) + '%';
    h += '<div class="pbd-financing-cost-line' + (i === cur ? ' pbd-financing-cost-cur' : '') + '" data-i="' + i + '">' +
      '<div class="pbd-financing-cost-r"><span class="pbd-financing-cost-nm"><b>' + l.n + '</b><i>' + l.b + '</i></span>' +
      '<em>' + f(l.bal,1) + '</em><em>' + f(l.bm + l.sp,2) + '%</em>' +
      '<em class="pbd-financing-cost-v ' + cls(r.tot) + '">' + sg(r.tot) + '</em></div>' +
      '<div class="pbd-financing-cost-bar"><u class="' + cls(r.tot) + '" style="' + pos + '"></u></div></div>';
  });
  root.querySelector('.pbd-financing-cost-rows').innerHTML = h;
  q('vh').innerHTML = v.h;
  q('net').textContent = (net < 0 ? '▼ ' : '▲ ') + sg(net);
  q('net').className = cls(net);
  q('bm').textContent = sg(bm); q('bm').className = cls(bm);
  q('sp').textContent = sg(sp); q('sp').className = cls(sp);
  var tot = Math.abs(bm) + Math.abs(sp);
  root.querySelector('.pbd-financing-cost-sb-bm').style.flexBasis = (Math.abs(bm)/tot*100).toFixed(2) + '%';
  root.querySelector('.pbd-financing-cost-sb-sp').style.flexBasis = (Math.abs(sp)/tot*100).toFixed(2) + '%';
  var ann = vals(365, 1).reduce(function(s,r){ return s + r.tot; }, 0);
  q('bps').textContent = 'NET ' + (ann < 0 ? 'COST ' : 'INCOME ') + f(Math.abs(ann) / (NAV*1e6) * 1e4, 1) + ' bps NAV p.a.';
  var l = L[cur], r = rs[cur];
  root.querySelector('.pbd-financing-cost-fx').innerHTML =
    '<b>' + l.n + '</b>: ' + f(l.bal,1) + 'M &times; ' + f(l.bm + l.sp,2) + '% &times; ' + v.d + '/360 = <b class="' + cls(r.tot) + '">' + sg(r.tot) + v.x + '</b><br>' +
    'benchmark ' + sg(r.bm) + v.x + ' &middot; spread ' + sg(r.sp) + v.x + ' (' + (l.sp >= 0 ? '+' : '−') + Math.round(Math.abs(l.sp)*100) + ' bps)';
}
root.querySelector('.pbd-financing-cost-rows').addEventListener('click', function(e){
  var el = e.target.closest('.pbd-financing-cost-line');
  if (el){ cur = Number(el.getAttribute('data-i')); render(); }
});
root.querySelectorAll('.pbd-financing-cost-seg button').forEach(function(b){
  b.addEventListener('click', function(){ view = Number(b.getAttribute('data-v')); render(); });
});
root.addEventListener('keydown', function(e){
  if (e.key === 'ArrowRight'){ view = Math.min(2, view+1); render(); e.preventDefault(); }
  else if (e.key === 'ArrowLeft'){ view = Math.max(0, view-1); render(); e.preventDefault(); }
  else if (e.key === 'ArrowDown'){ cur = Math.min(L.length-1, cur+1); render(); e.preventDefault(); }
  else if (e.key === 'ArrowUp'){ cur = Math.max(0, cur-1); render(); e.preventDefault(); }
});
render();

