var E = [
  {n:'PB US LLC', c:'PB-US', j:'US', basis:'SEC 15c3-3 · cap 140% × debit',          cp:140, debit:1120.0, pool:2412.6, u:[612.4,498.1,214.6,77.7]},
  {n:'PB INTL LTD', c:'PB-UK', j:'UK', basis:'Contractual cap · 140% × debit',         cp:140, debit:486.0,  pool:912.3,  u:[301.2,244.7,88.3,21.7]},
  {n:'PB EUROPE SE', c:'PB-EU', j:'EU', basis:'Right of use (SFTR Art.15) · 100% × debit', cp:100, debit:212.4, pool:388.0, u:[71.0,52.3,19.8,5.5]}
];
var U = ['Street stock loan','Repo / funding','Internal cover','Firm collateral'];
var COL = ['var(--c0)','var(--c1)','var(--c2)','var(--c3)'];
var cur = 0;
function q(k){ return root.querySelector('[data-k="'+k+'"]'); }
function r1(v){ return Math.round(v*10 + (v >= 0 ? 1e-7 : -1e-7))/10; }
function f(v,d){ return Math.abs(v).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d}); }
function sum(a){ return a.reduce(function(x,y){ return x+y; },0); }
function lr(vals,dp){
  var m = Math.pow(10,dp), tot = sum(vals);
  var raw = vals.map(function(v){ return v/tot*100*m; }), fl = raw.map(Math.floor);
  var rem = Math.round(100*m - sum(fl));
  var ix = raw.map(function(v,i){ return i; }).sort(function(a,b){ return (raw[b]-fl[b]) - (raw[a]-fl[a]); });
  for (var k = 0; k < rem; k++) fl[ix[k % ix.length]]++;
  return fl.map(function(v){ return v/m; });
}
function derive(e){
  var o = {n:e.n, c:e.c, j:e.j, basis:e.basis, debit:e.debit, pool:e.pool, u:e.u};
  o.cap = e.cap !== undefined ? e.cap : r1(e.debit * e.cp / 100);
  o.rh = r1(sum(e.u));
  o.used = o.rh / o.cap * 100;
  o.head = r1(o.cap - o.rh);
  o.seg = r1(o.pool - o.rh);
  o.uns = r1(o.rh - o.debit);
  return o;
}
var D = E.map(derive);
var T = derive({n:'ALL ENTITIES', c:'TOTAL', j:'', basis:'Aggregate · sum of entity caps', debit:r1(sum(D.map(function(d){ return d.debit; }))),
  pool:r1(sum(D.map(function(d){ return d.pool; }))), cap:r1(sum(D.map(function(d){ return d.cap; }))),
  u:[0,1,2,3].map(function(i){ return r1(sum(D.map(function(d){ return d.u[i]; }))); })});
var ALL = D.concat([T]);
function status(u){ return u > 100 ? ['pbd-rehyp-summary-br','BRCH'] : u >= 85 ? ['pbd-rehyp-summary-wt','WTCH'] : ['pbd-rehyp-summary-ok','OK']; }
function render(){
  var h = '';
  ALL.forEach(function(d,i){
    var s = status(d.used);
    h += '<tr data-i="' + i + '" class="' + (i === ALL.length-1 ? 'pbd-rehyp-summary-tot' : '') + (i === cur ? ' pbd-rehyp-summary-cur' : '') + '">' +
      '<td title="' + d.n + '"><b>' + d.c + '</b></td><td>' + f(d.debit,1) + '</td><td>' + f(d.cap,1) + '</td><td>' + f(d.rh,1) + '</td>' +
      '<td><span class="pbd-rehyp-summary-u ' + s[0] + '">' + f(d.used,1) + '%<small>' + s[1] + '</small></span></td></tr>';
  });
  root.querySelector('.pbd-rehyp-summary-tbl tbody').innerHTML = h;
  var d = ALL[cur];
  q('en').textContent = d.n;
  q('basis').textContent = d.basis;
  var segs = '';
  d.u.forEach(function(v,i){ segs += '<i data-u="' + i + '" style="width:' + (v/d.pool*100).toFixed(2) + '%;background:' + COL[i] + '" title="' + U[i] + '"></i>'; });
  root.querySelector('.pbd-rehyp-summary-segs').innerHTML = segs;
  root.querySelector('.pbd-rehyp-summary-cap').style.left = Math.min(100, d.cap/d.pool*100).toFixed(2) + '%';
  q('pool').textContent = 'MARGIN SECURITIES POOL ' + f(d.pool,1);
  var pct = lr(d.u.concat([d.seg]), 1), lg = '';
  d.u.forEach(function(v,i){
    lg += '<div data-u="' + i + '"><i class="pbd-rehyp-summary-sw" style="background:' + COL[i] + '"></i><span>' + U[i] + '</span><b>' + f(v,1) + '<small>' + f(pct[i],1) + '%</small></b></div>';
  });
  lg += '<div><i class="pbd-rehyp-summary-sw pbd-rehyp-summary-sw-seg"></i><span>Segregated</span><b>' + f(d.seg,1) + '<small>' + f(pct[4],1) + '%</small></b></div>';
  lg += '<div><i class="pbd-rehyp-summary-sw" style="background:#fff;width:2px"></i><span>Cap = ' + f(d.cap/d.pool*100,1) + '% pool</span><b>' + f(d.cap,1) + '</b></div>';
  root.querySelector('.pbd-rehyp-summary-lg').innerHTML = lg;
  var s = status(d.used);
  q('head').textContent = (d.head < 0 ? '−' : '') + f(d.head,1);
  q('head').className = s[0];
  q('seg').textContent = f(d.seg,1);
  q('uns').textContent = d.uns > 0 ? f(d.uns,1) : 'NIL';
  q('uns').className = d.uns > 0 ? 'pbd-rehyp-summary-wt' : 'pbd-rehyp-summary-ok';
  q('uns').title = 'Rehypothecated ' + f(d.rh,1) + ' − debit ' + f(d.debit,1);
}
function hl(i){
  root.querySelectorAll('.pbd-rehyp-summary-segs i').forEach(function(el){
    el.classList.toggle('pbd-rehyp-summary-hl', el.getAttribute('data-u') === i);
  });
}
root.querySelector('.pbd-rehyp-summary-tbl tbody').addEventListener('click', function(e){
  var tr = e.target.closest('tr');
  if (tr){ cur = Number(tr.getAttribute('data-i')); render(); }
});
var lgEl = root.querySelector('.pbd-rehyp-summary-lg');
lgEl.addEventListener('mouseover', function(e){ var el = e.target.closest('[data-u]'); hl(el ? el.getAttribute('data-u') : null); });
lgEl.addEventListener('mouseleave', function(){ hl(null); });
root.addEventListener('keydown', function(e){
  if (e.key === 'ArrowDown'){ cur = Math.min(ALL.length-1, cur+1); render(); e.preventDefault(); }
  else if (e.key === 'ArrowUp'){ cur = Math.max(0, cur-1); render(); e.preventDefault(); }
});
render();

