.pbd-cpty-exposure *{animation:none!important;transition:none!important}
}

js:
var P = [
  {n:'Northgate', fn:'Northgate Securities', r:'A+',   cds:48.2,  o:47.6,  eq:412.6, rq:251.8},
  {n:'Halden', fn:'Halden Prime', r:'A',    cds:61.4,  o:60.9,  eq:286.3, rq:170.4},
  {n:'Carrow', fn:'Carrow &amp; Co', r:'A-',   cds:94.7,  o:95.3,  eq:148.9, rq:98.3},
  {n:'Ostrander', fn:'Ostrander Bank', r:'BBB+', cds:142.3, o:139.8, eq:96.2,  rq:52.1},
  {n:'Veld', fn:'Veld Markets', r:'AA-',  cds:37.1,  o:37.1,  eq:58.4,  rq:44.0}
];
var cur = 0, staged = null, flash = -1, TARGET = 80;
var act = root.querySelector('.pbd-cpty-exposure-act');
function q(k){ return root.querySelector('[data-k="'+k+'"]'); }
function r1(v){ return Math.round(v*10 + (v >= 0 ? 1e-7 : -1e-7))/10; }
function f(v,d){ return Math.abs(v).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d}); }
function sum(a){ return a.reduce(function(x,y){ return x+y; },0); }
function lr(vals,dp){
  var m = Math.pow(10,dp), tot = sum(vals);
  var raw = vals.map(function(v){ return v/tot*100*m; }), fl = raw.map(Math.floor);
  var rem = Math.round(100*m - sum(fl));
  var ix = raw.map(function(v,i){ return i; }).sort(function(a,b){ return (raw[b]-fl[b]) - (raw[a]-fl[a]); });
  for (var k = 0; k < rem; k++) fl[ix[k % ix.length]]++;
  return fl.map(function(v){ return v/m; });
}
function ex(p){ return r1(p.eq - p.rq); }
function lim(p){ return p.cds < 75 ? 150 : p.cds < 125 ? 75 : 50; }
function tierTxt(p){ return p.cds < 75 ? 'CDS <75bp' : p.cds < 125 ? 'CDS 75-125bp' : 'CDS ≥125bp'; }
function use(p){ return ex(p) / lim(p) * 100; }
function st(u){ return u > 100 ? ['pbd-cpty-exposure-br','BRCH'] : u >= 85 ? ['pbd-cpty-exposure-wt','WTCH'] : ['pbd-cpty-exposure-ok','OK']; }
function render(){
  var exs = P.map(ex), sh = lr(exs,1), h = '';
  var teq = r1(sum(P.map(function(p){ return p.eq; }))), trq = r1(sum(P.map(function(p){ return p.rq; }))), tex = r1(teq - trq);
  var wcds = sum(P.map(function(p,i){ return exs[i]*p.cds; })) / sum(exs);
  P.forEach(function(p,i){
    var d = r1(p.cds - p.o), u = use(p), s = st(u);
    var dc = d > 0 ? 'pbd-cpty-exposure-wide' : d < 0 ? 'pbd-cpty-exposure-tight' : 'pbd-cpty-exposure-flat';
    h += '<tr data-i="' + i + '"' + (i === cur ? ' class="pbd-cpty-exposure-cur"' : '') + '>' +
      '<td title="' + p.fn + '"><b>' + p.n + '</b><i>' + p.r + '</i></td>' +
      '<td><span class="pbd-cpty-exposure-c' + (i === flash ? ' pbd-cpty-exposure-fl' : '') + '">' + f(p.cds,1) +
      '<small class="' + dc + '">' + (d > 0 ? '▲+' : d < 0 ? '▼−' : '') + f(d,1) + '</small></span></td>' +
      '<td>' + f(exs[i],1) + '</td><td>' + f(sh[i],1) + '%</td>' +
      '<td><span class="pbd-cpty-exposure-use ' + s[0] + '"><span class="pbd-cpty-exposure-pct">' + f(u,1) + '%' +
      '<span class="pbd-cpty-exposure-bar"><em style="width:' + Math.min(100,u).toFixed(1) + '%"></em></span></span><span class="pbd-cpty-exposure-st">' + s[1] + '</span></span></td></tr>';
  });
  root.querySelector('.pbd-cpty-exposure-tbl tbody').innerHTML = h;
  q('eq').textContent = f(teq,1);
  q('rq').textContent = f(trq,1);
  q('ex').textContent = f(tex,1);
  q('cds').textContent = f(wcds,1) + 'bp';
  flash = -1;
}
function proposal(i){
  var p = P[i], e = ex(p), u = use(p);
  if (u < 85) return {msg:'<b>' + p.fn + '</b> within limit · excess ' + f(e,1) + ' of ' + f(lim(p),1) + ' · headroom ' + f(lim(p) - e,1) + '<br>limit tier ' + tierTxt(p) + ' → ' + lim(p) + 'M'};
  var amt = r1(e - lim(p)*TARGET/100), best = -1;
  P.forEach(function(t,j){
    if (j === i) return;
    if (r1(lim(t) - ex(t)) - amt >= 0 && use(t) + amt/lim(t)*100 < 85 && (best < 0 || t.cds < P[best].cds)) best = j;
  });
  if (best < 0) return {msg:'<b>' + p.fn + '</b> ' + f(u,1) + '% of limit · no PB has headroom for ' + f(amt,1) + ' · escalate to COO'};
  var t = P[best];
  return {from:i, to:best, amt:amt, msg:'SWEEP <b>' + f(amt,1) + 'M</b> ' + p.n + ' → ' + t.n + ' (CDS ' + f(t.cds,1) + ')<br>post-use ' +
    f((e-amt)/lim(p)*100,1) + '% / ' + f((ex(t)+amt)/lim(t)*100,1) + '% · &#9166; to confirm'};
}
function stage(){
  var pr = proposal(cur);
  act.innerHTML = pr.msg;
  staged = pr.amt ? pr : null;
  act.className = 'pbd-cpty-exposure-act' + (staged ? ' pbd-cpty-exposure-staged' : '');
}
function confirmSweep(){
  var s = staged, a = P[s.from], b = P[s.to];
  a.eq = r1(a.eq - s.amt); b.eq = r1(b.eq + s.amt);
  act.innerHTML = 'SWEPT <b>' + f(s.amt,1) + 'M</b> ' + a.n + ' → ' + b.n + '<br>wire ref SWP-' + (40718 + Math.floor(Math.random()*900)) + ' · value today';
  act.className = 'pbd-cpty-exposure-act pbd-cpty-exposure-done';
  staged = null;
  render();
}
root.querySelector('.pbd-cpty-exposure-tbl tbody').addEventListener('click', function(e){
  var tr = e.target.closest('tr');
  if (tr){ cur = Number(tr.getAttribute('data-i')); render(); stage(); }
});
root.addEventListener('keydown', function(e){
  if (e.key === 'ArrowDown'){ cur = Math.min(P.length-1, cur+1); render(); stage(); e.preventDefault(); }
  else if (e.key === 'ArrowUp'){ cur = Math.max(0, cur-1); render(); stage(); e.preventDefault(); }
  else if (e.key === 'Enter'){ if (staged && staged.from === cur) confirmSweep(); else stage(); e.preventDefault(); }
  else if (e.key === 'Escape'){ staged = null; act.className = 'pbd-cpty-exposure-act'; act.innerHTML = 'Sweep cancelled'; }
});
function tick(){
  if (!root.isConnected) return;
  var i = Math.floor(Math.random()*P.length), p = P[i];
  p.cds = Math.max(5, r1(p.cds + (Math.random() - 0.5) * (p.cds > 100 ? 3 : 1.6)));
  flash = i;
  render();
  if (staged) stage();
  setTimeout(tick, 2600);
}
render();
stage();
setTimeout(tick, 2600);

