.pbd-fails-queue{--tx:#e3e8f1;--dim:#7d879b;--ln:rgba(255,255,255,.08);--up:#3ddc97;--dn:#ff6b6b;--wr:#f5b83d;--ac:#6aa8ff;box-sizing:border-box;width:100%;display:flex;flex-direction:column;gap:6px;padding:9px 10px 8px;background:linear-gradient(180deg,#121722 0%,#0b0e15 100%);border:1px solid var(--ln);border-radius:8px;color:var(--tx);font:10px/1.25 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;outline:none}
.pbd-fails-queue:focus-visible{box-shadow:0 0 0 1px var(--ac)}
