.pbd-fails-queue-chips button:hover{color:var(--tx)}
.pbd-fails-queue-chips button[aria-selected="true"]{border-color:rgba(106,168,255,.55);background:rgba(106,168,255,.16);color:#d4e4ff}
.pbd-fails-queue-scroll{max-height:150px;overflow:auto;border-top:1px solid var(--ln);scrollbar-width:thin;scrollbar-color:#2a3242 transparent}
