.pbd-fails-queue-tbl td:nth-child(2),.pbd-fails-queue-tbl td:last-child{text-align:center}
.pbd-fails-queue-tbl tbody tr{cursor:pointer}
.pbd-fails-queue-tbl tbody tr:hover{background:rgba(255,255,255,.035)}
.pbd-fails-queue-tbl tr.pbd-fails-queue-cur{background:rgba(106,168,255,.13);box-shadow:inset 2px 0 0 var(--ac)}
.pbd-fails-queue-tbl tr.pbd-fails-queue-out td{animation:pbd-fails-queue-out .35s ease-in forwards}
.pbd-fails-queue-d{display:inline-block;min-width:26px;padding:0 2px;border-radius:2px;font:700 7.5px/1.35 ui-monospace,Menlo,Consolas,monospace;letter-spacing:.04em}
.pbd-fails-queue-ftd{background:rgba(255,107,107,.16);color:#ff8a8a}
.pbd-fails-queue-ftr{background:rgba(106,168,255,.16);color:#9cc2ff}
