.pbd-fails-queue-s2{background:rgba(255,107,107,.2);color:#ff8a8a}
.pbd-fails-queue-det{min-height:42px;padding:4px 6px;border:1px solid var(--ln);border-radius:4px;background:rgba(255,255,255,.02);font:8.5px/1.45 ui-monospace,Menlo,Consolas,monospace;color:#b8c2d3;font-variant-numeric:tabular-nums}
.pbd-fails-queue-det b{color:var(--tx)}
.pbd-fails-queue-det b.pbd-fails-queue-pos{color:var(--up)}
.pbd-fails-queue-det b.pbd-fails-queue-neg{color:var(--dn)}
.pbd-fails-queue-det em{font-style:normal;color:var(--dim)}
.pbd-fails-queue-empty td{padding:10px 4px!important;text-align:center!important;color:var(--dim)!important;font-weight:400!important}
.pbd-fails-queue-hint{display:flex;justify-content:space-between;gap:6px;font-size:7.5px;letter-spacing:.05em;color:#5b6477;white-space:nowrap}
.pbd-fails-queue-hint span:first-child{min-width:0;overflow:hidden;text-overflow:ellipsis}
.pbd-fails-queue-hint span:last-child{font-family:ui-monospace,Menlo,Consolas,monospace;color:var(--up)}
@keyframes pbd-fails-queue-out{0%{opacity:1}100%{opacity:0;background:rgba(61,220,151,.25)}}
@media (prefers-reduced-motion: reduce){
.pbd-fails-queue-tbl tr.pbd-fails-queue-out td{animation:none}
.pbd-fails-queue *{animation:none!important;transition:none!important}
}

js:
var RATE = {LS:[1.00,'liquid share'], IS:[0.50,'illiquid share'], SB:[0.10,'sovereign bond'], CB:[0.20,'corporate bond']};
var F = [
  {t:'VAR1 GY',   i:'DE000A0TGJ55', d:'FTD', q:30000,    p:7.84,    k:'IS', a:9, csd:'CBF',               why:'Borrow not sourced · name on HTB list'},
  {t:'VW 3.75 30',i:'XS2491738352', d:'FTD', q:5000000,  p:99.12,   k:'CB', a:6, csd:'Euroclear Bank',    why:'Chain fail · awaiting receipt from street'},
  {t:'TTE FP',    i:'FR0000120271', d:'FTD', q:120000,   p:58.15,   k:'LS', a:5, csd:'Euroclear France',  why:'Short of securities · loan recall pending'},
  {t:'DBR 2.6 34',i:'DE000BU2Z031', d:'FTR', q:25000000, p:101.35,  k:'SB', a:4, csd:'CBF',               why:'Cpty short · 60% partial offered'},
  {t:'SAP GY',    i:'DE0007164600', d:'FTR', q:42000,    p:189.20,  k:'LS', a:3, csd:'CBF',               why:'Cpty SSI mismatch · PSET BIC'},
  {t:'ASML NA',   i:'NL0010273215', d:'FTD', q:6500,     p:712.40,  k:'LS', a:2, csd:'Euroclear NL',      why:'Late affirmation · allocation break'},
  {t:'MC FP',     i:'FR0000121014', d:'FTR', q:3400,     p:648.30,  k:'LS', a:2, csd:'Euroclear France',  why:'Cpty lacks cash · DVP'},
  {t:'ADYEN NA',  i:'NL0012969182', d:'FTD', q:1800,     p:1412.00, k:'LS', a:1, csd:'Euroclear NL',      why:'Instruction on hold · release pending'},
  {t:'UCG IM',    i:'IT0005239360', d:'FTR', q:80000,    p:38.44,   k:'LS', a:1, csd:'Euronext Securities Milan', why:'Matching break · trade date'},
  {t:'SIE GY',    i:'DE0007236101', d:'FTD', q:15000,    p:172.60,  k:'LS', a:0, csd:'CBF',               why:'Missed RTS cut-off · next NTS cycle'}
];
var STATES = ['OPEN','CHSD','ESC'], filt = 'all', cur = F[0], settled = 0, settledPen = 0;
var MON = ['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'];
F.forEach(function(r){
  r.s = 0;
  r.v = Math.round((r.k === 'SB' || r.k === 'CB' ? r.q * r.p / 100 : r.q * r.p) * 100) / 100;
  r.pen = (r.d === 'FTD' ? -1 : 1) * Math.round(r.v * RATE[r.k][0] / 10000 * r.a * 100) / 100;
  var dt = new Date(2026, 8, 24), k = r.a;
  while (k > 0){ dt.setDate(dt.getDate() - 1); if (dt.getDay() !== 0 && dt.getDay() !== 6) k--; }
  r.isd = (dt.getDate() < 10 ? '0' : '') + dt.getDate() + '-' + MON[dt.getMonth()];
});
function q(k){ return root.querySelector('[data-k="'+k+'"]'); }
function f(v,d){ return Math.abs(v).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d}); }
function sg(v,d){ var r = Number(v.toFixed(d)); return (r > 0 ? '+' : r < 0 ? '−' : '') + f(r,d); }
function vis(){
  return F.filter(function(r){ return filt === 'all' || (filt === 'aged' ? r.a >= 5 : r.d === filt); });
}
function render(){
  var v = vis(), h = '';
  if (v.indexOf(cur) < 0) cur = v.filter(function(x){ return !x.out; })[0] || null;
  v.forEach(function(r){
    var ac = r.a >= 5 ? 'pbd-fails-queue-a5' : r.a >= 3 ? 'pbd-fails-queue-a3' : '';
    h += '<tr data-i="' + F.indexOf(r) + '" class="' + (r === cur ? 'pbd-fails-queue-cur' : '') + (r.out ? ' pbd-fails-queue-out' : '') + '">' +
      '<td>' + r.t + '</td><td><i class="pbd-fails-queue-d pbd-fails-queue-' + r.d.toLowerCase() + '">' + r.d + '</i></td>' +
      '<td>' + f(r.v/1000,0) + '</td><td class="' + ac + '">' + (r.a >= 5 ? '▲' : '') + r.a + 'd</td>' +
      '<td class="' + (r.pen > 0 ? 'pbd-fails-queue-pos' : r.pen < 0 ? 'pbd-fails-queue-neg' : '') + '">' + sg(r.pen,2) + '</td>' +
      '<td><i class="pbd-fails-queue-s pbd-fails-queue-s' + r.s + '">' + STATES[r.s] + '</i></td></tr>';
  });
  if (!v.length) h = '<tr class="pbd-fails-queue-empty"><td colspan="6">No fails in this view</td></tr>';
  root.querySelector('.pbd-fails-queue-tbl tbody').innerHTML = h;
  root.querySelectorAll('.pbd-fails-queue-chips button').forEach(function(b){
    b.setAttribute('aria-selected', b.getAttribute('data-f') === filt ? 'true' : 'false');
  });
  var ftd = 0, ftr = 0, pen = 0, open = 0;
  F.forEach(function(r){ if (r.out) return; open++; if (r.d === 'FTD') ftd += r.v; else ftr += r.v; pen += r.pen; });
  pen = Math.round(pen*100)/100;
  q('n').textContent = open;
  q('ftd').textContent = f(ftd/1000,0);
  q('ftr').textContent = f(ftr/1000,0);
  q('pen').textContent = sg(pen,2);
  q('pen').className = pen > 0 ? 'pbd-fails-queue-pos' : pen < 0 ? 'pbd-fails-queue-neg' : '';
  q('done').textContent = settled ? settled + ' SETTLED · ' + sg(settledPen,2) + ' €' : '';
  var det = root.querySelector('.pbd-fails-queue-det');
  if (!cur){ det.innerHTML = '<em>Queue clear for this filter.</em>'; return; }
  var rt = RATE[cur.k], bond = cur.k === 'SB' || cur.k === 'CB';
  det.innerHTML = '<b>' + cur.t + '</b> ' + cur.i + ' <em>· ' + cur.csd + ' · ISD ' + cur.isd + '</em><br>' +
    cur.d + ' ' + f(cur.q,0) + (bond ? ' nom @ ' : ' @ ') + f(cur.p,2) + ' = €' + f(cur.v,2) + '<br>' +
    '<em>' + cur.why + '</em><br>' +
    f(rt[0],2) + 'bp/d (' + rt[1] + ') × ' + cur.a + 'd = <b class="' + (cur.pen > 0 ? 'pbd-fails-queue-pos' : cur.pen < 0 ? 'pbd-fails-queue-neg' : '') + '">' + sg(cur.pen,2) + '</b> ' + (cur.d === 'FTD' ? 'payable' : 'receivable');
}
function move(dir){
  var v = vis(); if (!v.length) return;
  var i = v.indexOf(cur);
  cur = v[Math.max(0, Math.min(v.length-1, i + dir))];
  render();
  var sc = root.querySelector('.pbd-fails-queue-scroll'), tr = root.querySelector('.pbd-fails-queue-cur');
  if (tr){
    if (tr.offsetTop - 20 < sc.scrollTop) sc.scrollTop = tr.offsetTop - 20;
    else if (tr.offsetTop + tr.offsetHeight > sc.scrollTop + sc.clientHeight) sc.scrollTop = tr.offsetTop + tr.offsetHeight - sc.clientHeight;
  }
}
function settle(){
  if (!cur || cur.out) return;
  var r = cur, v = vis(), i = v.indexOf(r);
  r.out = true;
  cur = v.slice(i+1).concat(v.slice(0, i).reverse()).filter(function(x){ return !x.out; })[0] || null;
  render();
  setTimeout(function(){
    if (!root.isConnected) return;
    var k = F.indexOf(r);
    if (k < 0) return;
    settled++; settledPen = Math.round((settledPen + r.pen)*100)/100;
    F.splice(k, 1);
    render();
  }, 330);
}
root.querySelector('.pbd-fails-queue-tbl tbody').addEventListener('click', function(e){
  var tr = e.target.closest('tr[data-i]');
  if (tr){ cur = F[Number(tr.getAttribute('data-i'))]; render(); }
});
root.querySelectorAll('.pbd-fails-queue-chips button').forEach(function(b){
  b.addEventListener('click', function(){ filt = b.getAttribute('data-f'); render(); });
});
root.addEventListener('keydown', function(e){
  if (e.key === 'Enter' && e.target.tagName === 'BUTTON') return;
  if (e.key === 'ArrowDown'){ move(1); e.preventDefault(); }
  else if (e.key === 'ArrowUp'){ move(-1); e.preventDefault(); }
  else if (e.key === 'Enter'){ if (cur){ cur.s = Math.min(2, cur.s + 1); render(); } e.preventDefault(); }
  else if (e.key === 'r' || e.key === 'R'){ settle(); e.preventDefault(); }
});
render();

