js:
var B = [
  ['BYND',3.2,2950],['UPST',5.4,1020],['CVNA',14.1,640],['PLUG',8.6,360],['SMCI',7.4,290],['LCID',6.9,240],
  ['RIVN',11.8,150],['GME',9.3,70],['NVDA',52.7,18],['AAPL',64.5,15],['MSFT',48.2,15]
];
var SPLITS = [70,80,85,90], TIERS = ['SPCL','HTB','WARM','GC'], TCOL = ['var(--t0)','var(--t1)','var(--t2)','var(--t3)'];
var PER = [{k:'1D',d:1},{k:'MTD',d:24}];
var si = 1, pi = 0, cur = 0;
function q(k){ return root.querySelector('[data-k="'+k+'"]'); }
function g(v){ return Math.abs(v).toLocaleString('en-US',{maximumFractionDigits:0}); }
function f(v,d){ return Math.abs(v).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d}); }
function tier(fee){ return fee > 1000 ? 0 : fee > 300 ? 1 : fee > 35 ? 2 : 3; }
function sum(a){ return a.reduce(function(x,y){ return x+y; },0); }
function lr(vals,dp){
  var m = Math.pow(10,dp), tot = sum(vals);
  var raw = vals.map(function(v){ return v/tot*100*m; }), fl = raw.map(Math.floor);
  var rem = Math.round(100*m - sum(fl));
  var ix = raw.map(function(v,i){ return i; }).sort(function(a,b){ return (raw[b]-fl[b]) - (raw[a]-fl[a]); });
  for (var k = 0; k < rem; k++) fl[ix[k % ix.length]]++;
  return fl.map(function(v){ return v/m; });
}
root.querySelector('.pbd-seclending-split-opts').innerHTML = SPLITS.map(function(s,i){
  return '<button type="button" role="tab" data-s="' + i + '">' + s + '/' + (100-s) + '</button>';
}).join('');
function render(){
  var days = PER[pi].d, split = SPLITS[si], h = '';
  var rows = B.map(function(b){
    var exact = b[1] * 1e6 * b[2] / 1e4 / 360;
    var gr = Math.round(exact * days), fu = Math.round(gr * split / 100);
    return {t:b[0], bal:b[1], fee:b[2], ex:exact, g:gr, fu:fu, ag:gr - fu, tr:tier(b[2])};
  });
  var tb = Math.round(sum(rows.map(function(r){ return r.bal; }))*10)/10;
  var tg = sum(rows.map(function(r){ return r.g; })), tfu = sum(rows.map(function(r){ return r.fu; })), tag = tg - tfu;
  var avg = sum(rows.map(function(r){ return r.ex; })) * 360 / (tb*1e6) * 1e4;
  rows.forEach(function(r,i){
    h += '<tr data-i="' + i + '"' + (i === cur ? ' class="pbd-seclending-split-cur"' : '') + '><td><i style="background:' + TCOL[r.tr] + '"></i>' + r.t + '</td>' +
      '<td>' + f(r.bal,1) + '</td><td>' + g(r.fee) + '</td><td>' + g(r.g) + '</td><td>' + g(r.fu) + '</td><td>' + g(r.ag) + '</td></tr>';
  });
  root.querySelector('.pbd-seclending-split-tbl tbody').innerHTML = h;
  q('tb').textContent = f(tb,1); q('tf').textContent = g(avg); q('tg').textContent = g(tg); q('tfu').textContent = g(tfu); q('tag').textContent = g(tag);
  q('g').textContent = g(tg); q('fu').textContent = g(tfu); q('ag').textContent = g(tag); q('fee').textContent = f(avg,1) + 'bp';
  var bt = [0,0,0,0], rt = [0,0,0,0];
  rows.forEach(function(r){ bt[r.tr] += r.bal; rt[r.tr] += r.ex; });
  var bp = lr(bt,1), rp = lr(rt,1);
  function bar(p){ return p.map(function(v,i){ return '<i style="width:' + v + '%;background:' + TCOL[i] + '"></i>'; }).join(''); }
  q('mb').innerHTML = bar(bp); q('mv').innerHTML = bar(rp);
  root.querySelector('.pbd-seclending-split-lg').innerHTML = '<em>MIX %</em>' +
    TIERS.map(function(t,i){ return '<b><i style="background:' + TCOL[i] + '"></i>' + t + '</b>'; }).join('') +
    '<em>BALANCE</em>' + bp.map(function(v){ return '<span>' + f(v,1) + '</span>'; }).join('') +
    '<em>REVENUE</em>' + rp.map(function(v,i){ return '<span' + (v > bp[i] ? ' class="pbd-seclending-split-hot"' : '') + '>' + (v > bp[i] ? '▲' : '') + f(v,1) + '</span>'; }).join('');
  root.querySelectorAll('.pbd-seclending-split-opts button').forEach(function(b){ b.setAttribute('aria-selected', Number(b.getAttribute('data-s')) === si ? 'true' : 'false'); });
  root.querySelectorAll('.pbd-seclending-split-seg button').forEach(function(b){ b.setAttribute('aria-selected', Number(b.getAttribute('data-p')) === pi ? 'true' : 'false'); });
  var r = rows[cur];
  root.querySelector('.pbd-seclending-split-fx').innerHTML = '<b>' + r.t + '</b> ' + f(r.bal,1) + 'M &times; ' + g(r.fee) + 'bps &times; ' + days + '/360 = <b>$' + g(r.g) + '</b> &rarr; fund ' + split + '% $' + g(r.fu) + ' &middot; agent ' + (100-split) + '% $' + g(r.ag);
}
root.querySelector('.pbd-seclending-split-opts').addEventListener('click', function(e){
  var b = e.target.closest('button'); if (b){ si = Number(b.getAttribute('data-s')); render(); }
});
root.querySelectorAll('.pbd-seclending-split-seg button').forEach(function(b){
  b.addEventListener('click', function(){ pi = Number(b.getAttribute('data-p')); render(); });
});
root.querySelector('.pbd-seclending-split-tbl tbody').addEventListener('click', function(e){
  var tr = e.target.closest('tr'); if (tr){ cur = Number(tr.getAttribute('data-i')); render(); }
});
root.addEventListener('keydown', function(e){
  if (e.key === 'ArrowRight'){ si = Math.min(SPLITS.length-1, si+1); render(); e.preventDefault(); }
  else if (e.key === 'ArrowLeft'){ si = Math.max(0, si-1); render(); e.preventDefault(); }
  else if (e.key === 'ArrowDown' || e.key === 'ArrowUp'){
    cur = Math.max(0, Math.min(B.length-1, cur + (e.key === 'ArrowDown' ? 1 : -1))); render();
    var sc = root.querySelector('.pbd-seclending-split-scroll'), tr = root.querySelector('.pbd-seclending-split-cur');
    if (tr){
      if (tr.offsetTop - 20 < sc.scrollTop) sc.scrollTop = tr.offsetTop - 20;
      else if (tr.offsetTop + tr.offsetHeight + 20 > sc.scrollTop + sc.clientHeight) sc.scrollTop = tr.offsetTop + tr.offsetHeight + 20 - sc.clientHeight;
    }
    e.preventDefault();
  }
  else if (e.key === 'd' || e.key === 'D'){ pi = 0; render(); }
  else if (e.key === 'm' || e.key === 'M'){ pi = 1; render(); }
});
render();
